# okno sa zapne len so súhlasom prevádzky rezervačného systému (premenná ASISTENT_KALENDAR_URL) a so serverom na hostingu;
# rezervačná stránka potom stratí noindex a jej adresa (z canonical) pribudne do sitemap.xml
if [ -n "$KALENDAR" ] && [ -n "$FTP_SERVER" ]; then sed -i 's#<html lang="sk" data-motion="on"#<html lang="sk" data-motion="on" data-objednavka="https://www.headspa30.sk/asistent/api.php"#' _site/barbershop-30/index.html _site/barbershop-30/rezervacia.html; sed -i '/<meta name="robots" content="noindex">/d' _site/barbershop-30/rezervacia.html; R=$(sed -n 's#.*<link rel="canonical" href="\([^"]*\)".*#\1#p' _site/barbershop-30/rezervacia.html); sed -i "s#</urlset>#  <url>\n    <loc>$R</loc>\n    <changefreq>monthly</changefreq>\n    <priority>0.6</priority>\n  </url>\n</urlset>#" _site/barbershop-30/sitemap.xml; echo "objednávka zapnutá (rezervácia sa indexuje, je aj v sitemap.xml)"; else echo "objednávka vypnutá (chýba ASISTENT_KALENDAR_URL alebo FTP_SERVER)"; fi

